package com.jayaseelan.nexoramart.service;
import com.jayaseelan.nexoramart.dao.UserDAO; import com.jayaseelan.nexoramart.model.User; import com.jayaseelan.nexoramart.util.PasswordUtil; import com.jayaseelan.nexoramart.util.ValidationUtil;
public class AuthService{private final UserDAO dao;public AuthService(UserDAO d){dao=d;} public void register(String n,String e,String p,String role)throws Exception{n=n==null?"":n.trim();e=e==null?"":e.trim().toLowerCase();if(!ValidationUtil.name(n))throw new IllegalArgumentException("Enter a valid name.");if(!ValidationUtil.email(e))throw new IllegalArgumentException("Enter a valid email.");if(!ValidationUtil.password(p))throw new IllegalArgumentException("Password must contain at least 6 characters.");if(!"BUYER".equals(role)&&!"SELLER".equals(role))throw new IllegalArgumentException("Select Buyer or Seller.");if(dao.findByEmail(e)!=null)throw new IllegalArgumentException("Email is already registered.");dao.create(new User(0,n,e,PasswordUtil.hash(p),role));} public User login(String e,String p)throws Exception{if(e==null||p==null)return null;User u=dao.findByEmail(e.trim().toLowerCase());return u!=null&&u.isActive()&&PasswordUtil.matches(p,u.getPasswordHash())?u:null;}}
